  for (const [a, b] of tramos(a0, cal, tz)) {
    if (a >= b0) break;
    if (b <= a0) continue;
    total += Math.min(b, b0) - Math.max(a, a0);
  }
  return total / 60000;
}

function enHorarioLaboral(fecha, cal, tz) {
  const t = new Date(fecha).getTime();
  for (const [a, b] of tramos(t, cal, tz, 1)) {
    if (t >= a && t < b) return true;
  }
  return false;
