  if (!token) throw new Error('Falta HUBSPOT_PRIVATE_APP_TOKEN');
  const pausa = esperar || ((ms) => new Promise((r) => setTimeout(r, ms)));

  async function solicitud(method, ruta, body, { aceptar = [] } = {}) {
    let intento = 0;
