    },

    async completarTarea(id) {
      const r = await solicitud(
        'PATCH',
        `/crm/v3/objects/tasks/${id}`,
        { properties: { hs_task_status: 'COMPLETED' } },
        { aceptar: [404] },
      );
      return r.status === 404 ? null : r.body;
    },

    // ── Notas ──
