    case 'verificar_pago':
      return new Date(ahora + 4 * HORA);
    case 'enviar': {
      // fecha_entrega − 1 día, a las 09:00 hora local; si no hay fecha, 24 h.
      if (ctx.fechaEntrega && /^\d{4}-\d{2}-\d{2}/.test(ctx.fechaEntrega)) {
