  switch (tipo) {
    case 'contestar':
    case 'seguimiento':
      return true;
    case 'cotizar':
      return o <= orden('cotizado');
    case 'verificar_pago':
      return o < orden('pagado');
    case 'produccion':
    case 'enviar':
      return o >= orden('pagado');
    case 'confirmar':
      return o >= orden('enviado');
    default:
      return false;
  }
}

module.exports = {
  TIPOS_TAREA,
  TIPOS_SUGERIBLES,
  PRIORIDAD,
  nombreCliente,
  canalCliente,
  tituloTarea,
  vencimiento,
  tareaPermitida,
};

